-- CineDesk initial schema. Apply through Supabase migrations in a new project.
begin;
create extension if not exists pgcrypto;
create type public.workspace_role as enum ('owner','administrator','producer','director','assistant_director','cinematographer','production_manager','crew_member','viewer');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', avatar_path text, created_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name)) between 1 and 120), description text not null default '', logo_path text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.organization_memberships (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.workspace_role not null default 'viewer', created_at timestamptz not null default now(), primary key(organization_id,user_id));
create function public.is_org_member(oid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_memberships where organization_id=oid and user_id=auth.uid()) $$;
create function public.is_org_admin(oid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_memberships where organization_id=oid and user_id=auth.uid() and role in ('owner','administrator')) $$;
create function public.can_create_project(oid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_memberships where organization_id=oid and user_id=auth.uid() and role in ('owner','administrator','producer','director','production_manager')) $$;
create table public.projects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, title text not null check(length(trim(title)) between 1 and 180), production_type text not null default 'Short Film', genre text not null default '', logline text not null default '', synopsis text not null default '', director text not null default '', producer text not null default '', estimated_budget_cents bigint not null default 0 check(estimated_budget_cents>=0), currency text not null default 'BDT' check(currency in ('BDT','USD')), status text not null default 'Development' check(status in ('Development','Pre-Production','Production','Post-Production','Completed','Archived')), start_date date, target_date date, cover_path text, notes text not null default '', created_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,organization_id), check(target_date is null or start_date is null or target_date>=start_date));
create table public.project_memberships (project_id uuid not null references public.projects(id) on delete cascade, organization_id uuid not null, user_id uuid not null, role public.workspace_role not null default 'viewer', primary key(project_id,user_id), foreign key(project_id,organization_id) references public.projects(id,organization_id) on delete cascade, foreign key(organization_id,user_id) references public.organization_memberships(organization_id,user_id) on delete cascade);
create function public.can_read_project(pid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.projects p where p.id=pid and (public.is_org_admin(p.organization_id) or exists(select 1 from public.project_memberships pm where pm.project_id=p.id and pm.user_id=auth.uid()))) $$;
create function public.can_write_project(pid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.projects p where p.id=pid and (public.is_org_admin(p.organization_id) or exists(select 1 from public.project_memberships pm where pm.project_id=p.id and pm.user_id=auth.uid() and pm.role in ('producer','director','assistant_director','cinematographer','production_manager')))) $$;
create table public.scenes (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, number text not null, setting text not null default 'INT' check(setting in ('INT','EXT','INT/EXT')), location text not null default '', time_of_day text not null default 'DAY', description text not null default '', duration_seconds integer not null default 0 check(duration_seconds>=0), cast_names text[] not null default '{}', props text[] not null default '{}', notes text not null default '', status text not null default 'Planned' check(status in ('Planned','Scheduled','Completed')), position integer not null default 0, unique(project_id,number), unique(id,project_id));
create table public.shots (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, scene_id uuid, number text not null, description text not null default '', size text not null default 'Medium', angle text not null default 'Eye level', movement text not null default 'Static', camera text not null default '', lens text not null default '', frame_rate numeric(6,3) not null default 24 check(frame_rate>0), duration_seconds integer not null default 0 check(duration_seconds>=0), lighting_notes text not null default '', equipment text not null default '', operator_name text not null default '', status text not null default 'Planned' check(status in ('Planned','Ready','Completed')), reference_path text, notes text not null default '', position integer not null default 0, foreign key(scene_id,project_id) references public.scenes(id,project_id) on delete cascade, unique(id,project_id));
create table public.shooting_days (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, shoot_date date not null, start_time time not null default '07:00', end_time time not null default '18:00', location text not null default '', revision integer not null default 1 check(revision>0), notes text not null default '', unique(id,project_id), check(end_time>start_time));
create table public.scheduled_scenes (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, shooting_day_id uuid not null, scene_id uuid not null, position integer not null default 0, foreign key(shooting_day_id,project_id) references public.shooting_days(id,project_id) on delete cascade, foreign key(scene_id,project_id) references public.scenes(id,project_id) on delete cascade, unique(shooting_day_id,scene_id));
create table public.crew (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, name text not null, department text not null default '', role text not null default '', email text not null default '', phone text not null default '', availability text not null default '', notes text not null default '');
create table public.tasks (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, title text not null check(length(trim(title))>0), description text not null default '', assignee_name text not null default '', priority text not null default 'Medium' check(priority in ('Low','Medium','High','Urgent')), due_date date, status text not null default 'To Do' check(status in ('To Do','In Progress','In Review','Completed')), position integer not null default 0, created_at timestamptz not null default now());
create table public.budget_categories (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, name text not null, estimated_cents bigint not null default 0 check(estimated_cents>=0), unique(id,project_id));
create table public.expenses (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, category_id uuid, category text not null default 'Other', description text not null, department text not null default '', amount_cents bigint not null check(amount_cents>=0), currency text not null default 'BDT' check(currency in ('BDT','USD')), expense_date date not null default current_date, foreign key(category_id,project_id) references public.budget_categories(id,project_id));
create table public.call_sheets (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, shooting_day_id uuid, general_call time, contacts text not null default '', reporting_instructions text not null default '', individual_calls jsonb not null default '[]', equipment_reminders text not null default '', weather_manual text not null default '', safety_notes text not null default '', instructions text not null default '', foreign key(shooting_day_id,project_id) references public.shooting_days(id,project_id) on delete cascade);
create table public.project_files (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, name text not null, category text not null default 'Reference', storage_path text not null unique, mime_type text not null, size_bytes bigint not null check(size_bytes between 1 and 10485760), uploaded_by uuid not null default auth.uid() references auth.users(id), created_at timestamptz not null default now(), unique(id,project_id));
create table public.storyboard_assets (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, shot_id uuid, file_id uuid, caption text not null default '', foreign key(shot_id,project_id) references public.shots(id,project_id) on delete cascade, foreign key(file_id,project_id) references public.project_files(id,project_id) on delete cascade);
create table public.activities (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, actor_id uuid not null default auth.uid() references auth.users(id), description text not null, created_at timestamptz not null default now());
-- Admin functions execute with the owner's privileges; callers cannot select their role.
create function public.create_organization(name text, description text default '') returns uuid language plpgsql security definer set search_path='' as $$ declare oid uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.organizations(name,description,created_by) values(name,description,auth.uid()) returning id into oid; insert into public.organization_memberships values(oid,auth.uid(),'owner',now()); return oid; end $$;
create function public.add_project_creator() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.project_memberships(project_id,organization_id,user_id,role) values(new.id,new.organization_id,auth.uid(),'producer'); return new; end $$;
create trigger project_creator after insert on public.projects for each row execute function public.add_project_creator();
create function public.touch_project() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); if new.organization_id<>old.organization_id or new.created_by<>old.created_by then raise exception 'Project ownership cannot be changed'; end if; return new; end $$;
create trigger project_timestamp before update on public.projects for each row execute function public.touch_project();
alter table public.profiles enable row level security;
create policy profiles_self_read on public.profiles for select to authenticated using(id=auth.uid());
create policy profiles_self_insert on public.profiles for insert to authenticated with check(id=auth.uid());
create policy profiles_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.organizations enable row level security;
create policy org_read on public.organizations for select to authenticated using(public.is_org_member(id));
create policy org_update on public.organizations for update to authenticated using(public.is_org_admin(id)) with check(public.is_org_admin(id));
alter table public.organization_memberships enable row level security;
create policy membership_read on public.organization_memberships for select to authenticated using(public.is_org_member(organization_id));
-- Membership changes require a privileged server workflow after validating the actor.
-- No browser INSERT/UPDATE/DELETE policy: this prevents self-promotion and owner tampering.
alter table public.project_memberships enable row level security;
create policy project_members_read on public.project_memberships for select to authenticated using(public.can_read_project(project_id));
create policy project_members_insert on public.project_memberships for insert to authenticated with check(public.is_org_admin(organization_id) and role<>'owner');
create policy project_members_update on public.project_memberships for update to authenticated using(public.is_org_admin(organization_id)) with check(public.is_org_admin(organization_id) and role<>'owner');
create policy project_members_delete on public.project_memberships for delete to authenticated using(public.is_org_admin(organization_id));
alter table public.projects enable row level security;
create policy project_read on public.projects for select to authenticated using(public.can_read_project(id));
create policy project_insert on public.projects for insert to authenticated with check(public.can_create_project(organization_id) and created_by=auth.uid());
create policy project_update on public.projects for update to authenticated using(public.can_write_project(id)) with check(public.can_write_project(id));
create policy project_delete on public.projects for delete to authenticated using(public.is_org_admin(organization_id));
do $$ declare t text; begin foreach t in array array['scenes','shots','shooting_days','scheduled_scenes','crew','tasks','budget_categories','expenses','call_sheets','project_files','storyboard_assets','activities'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy tenant_read on public.%I for select to authenticated using (public.can_read_project(project_id))',t); execute format('create policy tenant_insert on public.%I for insert to authenticated with check (public.can_write_project(project_id))',t); execute format('create policy tenant_update on public.%I for update to authenticated using (public.can_write_project(project_id)) with check (public.can_write_project(project_id))',t); execute format('create policy tenant_delete on public.%I for delete to authenticated using (public.can_write_project(project_id))',t); execute format('create index on public.%I(project_id)',t); end loop; end $$;
create index on public.organization_memberships(user_id,organization_id);
create index on public.project_memberships(user_id,project_id);
create index on public.projects(organization_id,status);
create index on public.tasks(project_id,status,due_date);
create index on public.shooting_days(project_id,shoot_date);
revoke all on function public.is_org_member(uuid), public.is_org_admin(uuid), public.can_create_project(uuid), public.can_read_project(uuid), public.can_write_project(uuid), public.create_organization(text,text), public.add_project_creator(), public.touch_project() from public, anon;
grant execute on function public.is_org_member(uuid), public.is_org_admin(uuid), public.can_create_project(uuid), public.can_read_project(uuid), public.can_write_project(uuid), public.create_organization(text,text) to authenticated;
grant select,insert,update,delete on public.profiles, public.organizations, public.organization_memberships, public.projects, public.project_memberships, public.scenes, public.shots, public.shooting_days, public.scheduled_scenes, public.crew, public.tasks, public.budget_categories, public.expenses, public.call_sheets, public.project_files, public.storyboard_assets, public.activities to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('production-files','production-files',false,10485760,array['application/pdf','text/plain','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy production_file_read on storage.objects for select to authenticated using(bucket_id='production-files' and exists(select 1 from public.project_files f where f.storage_path=name and public.can_read_project(f.project_id)));
create policy production_file_insert on storage.objects for insert to authenticated with check(bucket_id='production-files' and exists(select 1 from public.project_files f where f.storage_path=name and f.uploaded_by=auth.uid() and public.can_write_project(f.project_id)));
create policy production_file_delete on storage.objects for delete to authenticated using(bucket_id='production-files' and exists(select 1 from public.project_files f where f.storage_path=name and public.can_write_project(f.project_id)));
commit;
